// one guard per System 1 game: system1_palette.h is generated by romconv
#if defined(ENABLE_STARJACK) || defined(ENABLE_REGULUS) || defined(ENABLE_UPNDOWN)

#include "system1.h"
#include "system1_palette.h"

using namespace system1_video;

namespace {

// main CPU address map (MAME system1_map)
constexpr uint16_t ROM_END = 0xc000;
constexpr uint16_t RAM_BASE = 0xc000;        // c000-efff: work, sprite, palette, video RAM
constexpr uint16_t PALETTE_BASE = 0xd800;
constexpr uint16_t COLLISION_BASE = 0xf000;
constexpr uint16_t MIX_RESET_BASE = 0xf400;
constexpr uint16_t SPR_COLLISION_BASE = 0xf800;
constexpr uint16_t SPR_RESET_BASE = 0xfc00;

// sound CPU address map (MAME sound_map)
constexpr uint16_t SOUND_ROM_END = 0x8000;
constexpr uint16_t SOUND_RAM_END = 0xa000;   // 8000-87ff, mirrored
constexpr uint16_t SOUND_RAM_MASK = 0x7ff;
constexpr uint16_t SN1_BASE = 0xa000;        // 2 MHz
constexpr uint16_t SN2_BASE = 0xc000;        // 4 MHz
constexpr uint16_t SOUND_LATCH_BASE = 0xe000;

// I/O ports (mask 0x1f)
constexpr uint8_t PORT_MASK = 0x1f;
constexpr uint8_t PORT_P2 = 0x04;
constexpr uint8_t PORT_SYSTEM = 0x08;
constexpr uint8_t PORT_DSW = 0x0c;           // 0c/0e SWA, 0d/0f SWB
constexpr uint8_t PORT_DSWB = 0x10;
constexpr uint8_t PORT_PPI = 0x14;
constexpr uint8_t PORT_END = 0x18;

// inputs, active low
constexpr uint8_t IN_BUTTON2 = 0x02;
constexpr uint8_t IN_BUTTON1 = 0x04;
constexpr uint8_t IN_DOWN = 0x10;
constexpr uint8_t IN_UP = 0x20;
constexpr uint8_t IN_RIGHT = 0x40;
constexpr uint8_t IN_LEFT = 0x80;
constexpr uint8_t IN_COIN1 = 0x01;
constexpr uint8_t IN_START1 = 0x10;

// START button: BUTTON_START with a COIN pin (EXTRA is then COIN) or the
// galagino controller, else START itself reports as BUTTON_EXTRA
#if defined(BTN_COIN_PIN) || defined(GALAGINO_CONTROLLER)
constexpr unsigned int START_KEY = BUTTON_START;
#else
constexpr unsigned int START_KEY = BUTTON_EXTRA;
#endif

// SN76489
constexpr uint8_t SN_LATCH = 0x80;
constexpr int SN_NOISE = 3;
constexpr int SN_TONE2 = 2;
constexpr int SN_NOISE_BASE = 4;             // N/512 in renderer noise units
constexpr int SN_FOLLOW_TONE2 = 3;

// mixer sources and palette blocks
constexpr uint8_t SOURCE_SPRITE = 0;
constexpr uint8_t SOURCE_FG = 1;
constexpr uint16_t FG_PENS = 0x200;
constexpr uint16_t BG_PENS = 0x400;

constexpr int STRIP_LINES = 8;
constexpr int TILE_SIZE = 8;

} // namespace

system1::system1(const Roms &r, const Config &c)
    : tile_rom(r.tiles), main_rom(r.main_cpu), sprite_rom(r.sprites),
      sound_rom(r.sound_cpu), lookup_prom(r.lookup), config(c) {
  // decompress largest first: Arena bin packing
  tiles = tile_rom.data();
  mainRom = main_rom.data();
  spriteRom = sprite_rom.data();
  soundRom = sound_rom.data();
  prom = lookup_prom.data();

  mainRomSize = main_rom.size();
  soundRomSize = sound_rom.size();
  tileMask = tile_rom.size() - 1;  // romconv asserts a power of two
  spriteBanks = sprite_rom.size() / SPRITE_BANK;
  firstStrip = rowOfX(config.vis.x1) / STRIP_LINES;
  lastStrip = rowOfX(config.vis.x0) / STRIP_LINES;
}

void system1::reset() {
  machineBase::reset();

  ppi.reset();
  mainIrq = false;
  soundIrq = false;

  snLatch[0] = snLatch[1] = 0;
  snNoiseReg[0] = snNoiseReg[1] = 0;
  memset(palette, 0, sizeof(palette));
  collision.reset();
  activeCount = 0;
}

unsigned char system1::opZ80(unsigned short Addr) {
  if (current_cpu == MAIN_CPU) {
    return Addr < mainRomSize ? mainRom[Addr] : mainRead(Addr);
  }
  return Addr < soundRomSize ? soundRom[Addr] : soundRead(Addr);
}

unsigned char system1::rdZ80(unsigned short Addr) {
  return current_cpu == MAIN_CPU ? mainRead(Addr) : soundRead(Addr);
}

void system1::wrZ80(unsigned short Addr, unsigned char Value) {
  if (current_cpu == MAIN_CPU) {
    mainWrite(Addr, Value);
    return;
  }
  soundWrite(Addr, Value);
}

uint8_t system1::mainRead(uint16_t a) {
  if (a < ROM_END) {
    return a < mainRomSize ? mainRom[a] : 0xff;
  }
  if (a < COLLISION_BASE) {
    return memory[a - RAM_BASE];
  }
  if (a < MIX_RESET_BASE) {
    return collision.mixRead(a);
  }
  if (a >= SPR_COLLISION_BASE && a < SPR_RESET_BASE) {
    return collision.sprRead(a);
  }
  return 0xff;
}

void system1::mainWrite(uint16_t a, uint8_t v) {
  if (a < ROM_END) {
    return;
  }

  if (a < COLLISION_BASE) {
    memory[a - RAM_BASE] = v;
    if (a >= PALETTE_BASE && a - PALETTE_BASE < PALETTE_USED) {
      palette[a - PALETTE_BASE] = system1_palette[v];
    }
    return;
  }

  if (a < MIX_RESET_BASE) {
    collision.mixClear(a);
  } else if (a < SPR_COLLISION_BASE) {
    collision.mixReset();
  } else if (a < SPR_RESET_BASE) {
    collision.sprClear(a);
  } else {
    collision.sprReset();
  }
}

uint8_t system1::soundRead(uint16_t a) {
  if (a < SOUND_ROM_END) {
    return a < soundRomSize ? soundRom[a] : 0xff;
  }
  if (a < SOUND_RAM_END) {
    return memory[SOUND_RAM + (a & SOUND_RAM_MASK)];
  }
  if (a >= SOUND_LATCH_BASE) {
    return ppi.ackA();
  }
  return 0xff;
}

void system1::soundWrite(uint16_t a, uint8_t v) {
  if (a < SOUND_ROM_END) {
    return;
  }

  if (a < SOUND_RAM_END) {
    memory[SOUND_RAM + (a & SOUND_RAM_MASK)] = v;
  } else if (a >= SN1_BASE && a < SN2_BASE) {
    snWrite(0, v);
  } else if (a < SOUND_LATCH_BASE) {
    snWrite(1, v);
  }
}

unsigned char system1::inZ80(unsigned short Port) {
  if (current_cpu != MAIN_CPU) {
    return 0xff;
  }

  const uint8_t p = Port & PORT_MASK;
  if (p < PORT_P2) {
    return readP1();
  }
  if (p < PORT_SYSTEM) {
    return 0xff;  // P2, cocktail only
  }
  if (p < PORT_DSW) {
    game_started = 1;
    return readSystem();
  }
  if (p < PORT_DSWB) {
    return (p & 1) ? dswB() : dswA();
  }
  if (p < PORT_PPI) {
    return dswB();
  }
  return ppi.read(p - PORT_PPI);
}

void system1::outZ80(unsigned short Port, unsigned char Value) {
  const uint8_t p = Port & PORT_MASK;
  if (current_cpu != MAIN_CPU || p < PORT_PPI || p >= PORT_END) {
    return;
  }
  ppi.write(p - PORT_PPI, Value);
}

// FIRE drives BUTTON1; galagino controller B, or START in two weapon games
// (Regulus bomb), drives BUTTON2
uint8_t system1::readP1() {
  const unsigned int k = input->buttons_get();
  uint8_t v = 0xff;
  if (k & BUTTON_FIRE) {
    v &= ~IN_BUTTON1;
  }
  if ((k & BUTTON_B) || (config.startButton2 && (k & START_KEY))) {
    v &= ~IN_BUTTON2;
  }
  if (k & BUTTON_DOWN) {
    v &= ~IN_DOWN;
  }
  if (k & BUTTON_UP) {
    v &= ~IN_UP;
  }
  if (k & BUTTON_RIGHT) {
    v &= ~IN_RIGHT;
  }
  if (k & BUTTON_LEFT) {
    v &= ~IN_LEFT;
  }
  return v;
}

uint8_t system1::readSystem() {
  const unsigned int k = input->buttons_get();
  uint8_t v = 0xff;
  if (k & BUTTON_COIN) {
    v &= ~IN_COIN1;
  }
  if (k & BUTTON_START) {
    v &= ~IN_START1;
  }
  return v;
}

// Renderer units (audio.cpp sn76489_render_buffer): tone toggles every
// period units, noise shifts every period << 3 units, 1 unit = 16 clocks.
void system1::snWrite(int chip, uint8_t d) {
  if (d & SN_LATCH) {
    snLatch[chip] = (d >> 4) & 0x07;  // channel * 2 + volume flag
  }
  const int ch = snLatch[chip] >> 1;
  const bool volume = snLatch[chip] & 1;

  if (volume) {
    sn_volume[chip][ch] = d & 0x0f;
    return;
  }

  if (ch == SN_NOISE) {
    snNoiseReg[chip] = d & 0x07;
    snNoise(chip);
    return;
  }

  int &period = sn_period[chip][ch];
  if (d & SN_LATCH) {
    period = (period & 0x3f0) | (d & 0x0f);
  } else {
    period = (period & 0x00f) | ((d & 0x3f) << 4);
  }

  if (ch == SN_TONE2) {
    snNoise(chip);
  }
}

// noise rate N/512, N/1024, N/2048 or tone 2 output (shifts every 2 tone
// periods, MAME sn76496); white/periodic not modeled
void system1::snNoise(int chip) {
  const int rate = snNoiseReg[chip] & 0x03;
  const int p = rate == SN_FOLLOW_TONE2 ? (sn_period[chip][SN_TONE2] >> 2) : (SN_NOISE_BASE << rate);
  sn_period[chip][SN_NOISE] = p > 0 ? p : 1;
}

void system1::run_frame(void) {
  for (int line = 0; line < FRAME_LINES; line++) {
    if (line % SOUND_IRQ_PERIOD == SOUND_IRQ_FIRST) {
      soundIrq = true;
    }
    irqLines();

    current_cpu = MAIN_CPU;
    for (int i = 0; i < MAIN_STEPS_PER_LINE; i++) {
      StepZ80(&cpu[MAIN_CPU]);
    }

    // sound command written by the main CPU in this slice
    current_cpu = SOUND_CPU;
    if (ppi.takeNmi()) {
      IntZ80(&cpu[SOUND_CPU], INT_NMI);
    }
    for (int i = 0; i < SOUND_STEPS_PER_LINE; i++) {
      StepZ80(&cpu[SOUND_CPU]);
    }

    if (line == VBLANK_LINE) {
      startVblank();
    }
  }
}

// Collision of the frame just shown, latch the video state, main IRQ.
void system1::startVblank() {
  const uint8_t *vram = &memory[VIDEO_RAM];

  const Collision::Frame f = {&memory[SPRITE_RAM], spriteRom, spriteBanks, vram,
                              tiles, tileMask, prom, ppi.portB(), config.vis};
  collision.scan(f);

  vblank.publish([this, vram](VideoState &v) {
    memcpy(v.sprite_ram, &memory[SPRITE_RAM], sizeof(v.sprite_ram));
    memcpy(v.bg_page, vram, sizeof(v.bg_page));
    v.scroll_x_lo = vram[SCROLL_X_LO];
    v.scroll_x_hi = vram[SCROLL_X_HI];
    v.scroll_y = vram[SCROLL_Y];
    v.mode = ppi.portB();
  });

  mainIrq = true;
}

// IRQs are HOLD_LINE in MAME: kept until the CPU accepts them, so one that
// lands in a DI section (e.g. the sound NMI handler) is delayed, not lost.
void system1::irqLines() {
  if (mainIrq && (cpu[MAIN_CPU].IFF & IFF_1)) {
    mainIrq = false;
    current_cpu = MAIN_CPU;
    IntZ80(&cpu[MAIN_CPU], INT_IRQ);
  }
  if (soundIrq && (cpu[SOUND_CPU].IFF & IFF_1)) {
    soundIrq = false;
    current_cpu = SOUND_CPU;
    IntZ80(&cpu[SOUND_CPU], INT_IRQ);
  }
}

// Visible sprites with their widest row, so strips can skip them cheaply.
void system1::prepare_frame(void) {
  vblank.read(video);
  activeCount = 0;
  if (video.mode & VIDEO_BLANK) {
    return;
  }

  Sprite list[SPRITES];
  const int count = decodeSprites(video.sprite_ram, spriteBanks, list);
  for (int n = 0; n < count; n++) {
    const Sprite &s = list[n];
    if (s.bottom <= 0 || s.top >= VIS_LINES) {
      continue;
    }

    const uint8_t *bank = spriteRom + s.bank * SPRITE_BANK;
    const int y0 = s.top > 0 ? s.top : 0;
    const int y1 = s.bottom < VIS_LINES ? s.bottom : VIS_LINES;
    int width = 0;
    for (int y = y0; y < y1; y++) {
      const int w = walkRow(bank, rowAddr(s, y), [](int, uint8_t) {});
      width = w > width ? w : width;
    }

    const int x0 = spriteX(s.x);
    if (width == 0 || x0 > config.vis.x1 || x0 + width <= config.vis.x0) {
      continue;
    }

    ActiveSprite &a = active[activeCount++];
    a.s = s;
    a.number = n;
    a.x0 = x0;
    a.width = width;
  }
}

void system1::render_row(short strip) {
  if (strip < firstStrip || strip > lastStrip || (video.mode & VIDEO_BLANK)) {
    return;
  }
  drawSprites(strip);
  mixStrip(strip);
}

// Sprite pens (sprite * 16 + nibble, never 0) into frame_buffer, later wins.
void system1::drawSprites(int strip) {
  const int firstRow = strip * STRIP_LINES;
  const int xHi = xOfRow(firstRow);
  const int xLo = xOfRow(firstRow + STRIP_LINES - 1);

  for (int a = 0; a < activeCount; a++) {
    const ActiveSprite &as = active[a];
    if (as.x0 > xHi || as.x0 + as.width <= xLo) {
      continue;
    }

    const uint8_t *bank = spriteRom + as.s.bank * SPRITE_BANK;
    const uint16_t penBase = as.number * PENS_PER_SPRITE;
    const int y0 = as.s.top > 0 ? as.s.top : 0;
    const int y1 = as.s.bottom < VIS_LINES ? as.s.bottom : VIS_LINES;
    for (int y = y0; y < y1; y++) {
      walkRow(bank, rowAddr(as.s, y), [&](int i, uint8_t c) {
        const int x = as.x0 + i;
        if (c == 0 || x < xLo || x > xHi) {
          return;
        }
        frame_buffer[(rowOfX(x) - firstRow) * VIS_LINES + y] = penBase | c;
      });
    }
  }
}

// Per pixel: fg + bg tile pixels, the lookup PROM picks the layer (MAME
// video_update_common). One tile word covers 8 output columns of a row.
// Hot loop: per tile constants hoisted, tile words shifted 3 bits per pixel.
void system1::mixStrip(int strip) {
  const uint8_t *fgPage = &memory[VIDEO_RAM + PAGE_BYTES];  // fixed layer, read live
  const uint8_t *bgPage = video.bg_page;
  const uint32_t (*const tw)[8] = tiles;
  const uint16_t mask = tileMask;
  const uint8_t *const mix = prom;
  const uint16_t *const pal = palette;
  const int scroll = bgScroll(video.scroll_x_lo, video.scroll_x_hi);
  const uint8_t scrollY = video.scroll_y;

  for (int l = 0; l < STRIP_LINES; l++) {
    const int x = xOfRow(strip * STRIP_LINES + l);
    const uint8_t bx = bgCol(2 * x, scroll);
    uint16_t *out = &frame_buffer[l * VIS_LINES];

    // bg tile entered mid-tile at y 0 when scroll_y is not a multiple of 8
    uint8_t by = scrollY;
    int bgLeft = 0;
    uint32_t bw = 0;
    uint8_t bgMix = 0;
    const uint16_t *bgPal = pal;

    for (int ty = 0; ty < VIS_LINES / TILE_SIZE; ty++) {
      const Tile ft = tileAt(fgPage, ty * PAGE_COLS + (x >> 3));
      uint32_t fw = tw[ft.code & mask][x & 7];
      const uint8_t fgMix = mixIndex(true, 1, ft.color, 1, 0);
      const uint16_t *fgPal = &pal[FG_PENS | tilePen(ft.color, 0)];

      for (int r = 0; r < TILE_SIZE; r++, out++, by++) {
        if (bgLeft == 0) {
          const Tile bt = tileAt(bgPage, (by >> 3) * PAGE_COLS + (bx >> 3));
          bw = tw[bt.code & mask][bx & 7] << (3 * (by & 7));
          bgMix = mixIndex(true, 1, 0, 1, bt.color);
          bgPal = &pal[BG_PENS | tilePen(bt.color, 0)];
          bgLeft = TILE_SIZE - (by & 7);
        }
        bgLeft--;

        const uint8_t fp = (fw >> 21) & 7;
        const uint8_t bp = (bw >> 21) & 7;
        fw <<= 3;
        bw <<= 3;

        const uint16_t spr = *out;
        const uint8_t idx = fgMix | bgMix | (spr ? 0 : 0x01) | (fp ? 0 : 0x02) | (bp ? 0 : 0x10);
        const uint8_t source = mix[idx] & MIX_SOURCE;
        if (source == SOURCE_SPRITE) {
          *out = pal[spr];
        } else if (source == SOURCE_FG) {
          *out = fgPal[fp];
        } else {
          *out = bgPal[bp];
        }
      }
    }
  }
}

#endif // System 1 games
